#!/usr/bin/env python3
"""Original SMPC RTC/INTBACK/IRQ guest. MIT: adjacent LICENSE."""
import argparse
import hashlib
import importlib.util
from pathlib import Path
import struct
HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('assembler', HERE.parents[1] / 'homebrew/star-collector/build.py')
assembler = importlib.util.module_from_spec(spec)
spec.loader.exec_module(assembler)


def byte(address, value):
    return f'load {address:#x},r1\nload {value:#x},r0\nmov.b r0,@r1\n'


def issue(command):
    return byte(0x100063, 1) + byte(0x10001f, command)


def idle(label):
    return f'load 0x100063,r1\n{label}:\nmov.b @r1,r0\ntst #1,r0\nbf {label}\n'


def program():
    s = 'mov #0,r0\nldc r0,sr\nload 0x05fe00a0,r1\nload 0xbf7f,r0\nmov.l r0,@r1\n'
    for i, value in enumerate([0x20,0x24,0x32,0x29,0x12,0x34,0x56]): s += byte(0x100001+i*2, value)
    s += issue(0x16) + idle('time_done')
    for i, value in enumerate([0x12,0x34,0x56,0x78]): s += byte(0x100001+i*2,value)
    s += issue(0x17) + idle('memory_done')
    for i, value in enumerate([1,0x0a,0xf0]): s += byte(0x100001+i*2,value)
    s += issue(0x10)
    s += 'load 0x100061,r1\nwait_status:\nmov.b @r1,r0\ntst #64,r0\nbt wait_status\n'
    s += 'load 0x100021,r1\nload 0x06008000,r8\nmov #16,r2\ncopy_status:\nmov.b @r1,r0\nmov.b r0,@r8\nadd #2,r1\nadd #1,r8\ndt r2\nbf copy_status\n'
    s += byte(0x100001, 0x81) + idle('input_done')
    s += 'load 0x100021,r1\nload 0x06008020,r8\nmov #16,r2\ncopy_input:\nmov.b @r1,r0\nmov.b r0,@r8\nadd #2,r1\nadd #1,r8\ndt r2\nbf copy_input\n'
    s += 'load 0x600d,r0\nload 0x06008044,r1\nmov.l r0,@r1\nsleep\n'
    return s


def build():
    rom = bytearray(524288)
    struct.pack_into('>II', rom, 0, 0x200, 0x06100000)
    struct.pack_into('>I', rom, 0x47*4, 0x1800)
    main = assembler.assemble(program(), base=0x200)
    assert len(main) < 0x1600
    rom[0x200:0x200+len(main)] = main
    handler = assembler.assemble('load 0x06008040,r12\nmov.l @r12,r13\nadd #1,r13\nmov.l r13,@r12\nrte\nnop', base=0x1800)
    rom[0x1800:0x1800+len(handler)] = handler
    text = ['# Original SMPC RTC/INTBACK/IRQ BIOS fixture. MIT: adjacent LICENSE.',
            '# Generated by build_smpc.py; all status/input reads and mailboxes execute as SH-2 guest code.']
    for address in range(0,len(rom),16):
        chunk = rom[address:address+16]
        if any(chunk): text.append(f'{address:04X} '+' '.join(f'{word:04X}' for word in struct.unpack('>8H',chunk)))
    return '\n'.join(text)+'\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    text, digest = build()
    path = HERE/'smpc.hex'
    if args.check:
        assert path.read_text() == text, 'Rebuild smpc.hex'
    else:
        path.write_text(text)
    print(f'{"Verified" if args.check else "Built"} smpc.hex; expanded ROM SHA-256 {digest}')
